INSERT INTO public.moduls (id, nomor_modul, judul, deskripsi, created_at, gambar) VALUES
(5, 1, 'Berpikir Komputasional', 'Mengidentifikasi permasalahan kompleks dalam kehidupan sehari-hari. Menerapkan langkah berpikir komputasional (dekomposisi, pola, abstraksi, algoritma) untuk menyusun solusi. Mengkomunikasikan hasil pemecahan masalah secara logis dan sistematis.', '2026-01-28T21:45:56.351908+07:00', '/imageAssets/modul/berpikirkomputasional.png'),
(6, 2, 'Literasi Digital', 'Memahami konsep dasar multimedia dan komponen pembentuknya (teks, gambar, audio, video, animasi). Menerapkan prinsip dasar pembuatan konten digital yang informatif dan etis. Menghasilkan dan menyebarkan (mendiseminasikan) konten digital sederhana secara bertanggung jawab.', '2026-01-28T21:46:34.220251+07:00', '/imageAssets/modul/literasidigital.png'),
(7, 3, 'Algoritma & Dasar Pemrograman', 'Membandingkan beberapa algoritma dan menerapkannya dalam bentuk kode sederhana (berbasis teks) untuk menghasilkan output.', '2026-01-28T21:47:24.488781+07:00', '/imageAssets/modul/algoritmapemrograman.png'),
(8, 4, 'Analisis Data', 'Memahami konsep dasar basis data dan menerapkan pengolahan data sederhana pada sistem basis data, sebagai dasar bagi kecerdasan buatan yang bergantung pada data terstruktur', '2026-01-28T21:47:47.477321+07:00', '/imageAssets/modul/analisisdata.png'),
(9, 5, 'Cerdas dan Etis Bersama AI', 'Memahami bagaimana KA mengenali pola citra dan suara, dan memahami profesi di bidang KA. memahami bahwa manusia harus memikul tanggung jawab etika dan hukum atas penggunaan KA sehingga pada kondisi tertentu pengambilan keputusan tidak sepenuhnya diserahkan pada KA.', '2026-01-28T21:48:02.069495+07:00', '/imageAssets/modul/etikaai.png'),
(10, 6, 'Pemanfaatan dan Pengembangan AI', 'Memahami bahwa manusia harus memikul tanggung jawab etika dan hukum atas penggunaan KA sehingga pada kondisi tertentu pengambilan keputusan tidak sepenuhnya diserahkan pada KA.', '2026-01-28T21:48:22.810556+07:00', '/imageAssets/modul/aigeneratif.png'),
(11, 1, 'tes', 'tes', '2026-02-28T14:28:09.379652+07:00', NULL)
ON CONFLICT (id) DO UPDATE SET nomor_modul = EXCLUDED.nomor_modul, judul = EXCLUDED.judul, deskripsi = EXCLUDED.deskripsi, created_at = EXCLUDED.created_at, gambar = EXCLUDED.gambar;

INSERT INTO public.pelajarans (id, created_at, judul, bagian, id_modul, deskripsi) VALUES
(5, '2026-01-29T00:23:50.721401+07:00', 'Pengenalan Algoritma', 1, 7, 'Mengenalkan algoritma sebagai langkah-langkah logis untuk menyelesaikan masalah.'),
(6, '2026-01-29T00:24:23.065508+07:00', 'Bentuk Representasi Algoritma', 2, 7, 'Membahas cara menuliskan algoritma dalam bentuk narasi, pseudocode, dan flowchart.'),
(7, '2026-01-29T00:24:39.14756+07:00', 'Struktur Kontrol Algoritma', 3, 7, 'Menjelaskan pengaturan alur algoritma menggunakan sequence, selection, dan looping.'),
(8, '2026-01-29T00:25:03.773216+07:00', 'Algoritma Searching & Sorting', 4, 7, 'Mempelajari cara mencari dan mengurutkan data menggunakan algoritma dasar.'),
(9, '2026-01-29T00:25:21.564525+07:00', 'Pemrograman Berbasis Teks', 5, 7, 'Mengubah algoritma menjadi kode program berbasis teks yang dapat dijalankan.'),
(10, '2026-01-29T00:25:36.264405+07:00', 'Debugging', 6, 7, 'Mempelajari cara menemukan dan memperbaiki kesalahan pada algoritma atau program.'),
(11, '2026-02-27T07:41:44.629339+07:00', 'Apa itu Berpikir Komputasional?', 1, 5, 'Mengenalkan konsep berpikir komputasional sebagai cara berpikir logis dan sistematis untuk menyelesaikan masalah. Peserta didik memahami pentingnya keterampilan ini dalam kehidupan sehari-hari, seperti membuat keputusan, mengatur aktivitas, dan menemukan solusi secara efektif.'),
(12, '2026-02-27T07:42:11.580823+07:00', 'Dekomposisi: Memecah Masalah Kompleks', 2, 5, 'Mengajarkan cara memecah masalah besar menjadi bagian-bagian kecil yang lebih mudah dipahami dan diselesaikan. Dengan dekomposisi, peserta didik belajar menangani masalah secara bertahap sehingga solusi lebih mudah ditemukan'),
(13, '2026-02-27T07:42:55.388583+07:00', 'Pengenalan Pola: Menemukan Kemiripan', 3, 5, 'Mengenali pola atau kesamaan dalam berbagai situasi atau masalah. Dengan menemukan pola, kamu dapat menyelesaikan masalah lebih cepat karena solusi yang sama dapat digunakan pada situasi yang mirip'),
(14, '2026-02-27T07:43:50.123362+07:00', 'Abstraksi: Fokus pada Hal Penting', 4, 5, 'Belajar menyaring informasi dengan fokus pada hal-hal yang penting dan relevan, serta mengabaikan detail yang tidak diperlukan. Kemampuan ini membantu memahami inti masalah dan membuat solusi lebih sederhana'),
(15, '2026-02-27T07:44:19.81298+07:00', 'Menyusun Langkah (Algoritma) Pemecahan Masalah', 5, 5, 'Mengenalkan cara menyusun langkah-langkah logis dan berurutan untuk menyelesaikan masalah. Peserta didik belajar membuat solusi sistematis yang mudah diikuti dan dapat diterapkan kembali pada situasi serupa.'),
(16, '2026-02-27T07:44:57.383051+07:00', 'Penerapan Berpikir Komputasional di Dunia Nyata', 6, 5, 'Menggabungkan dekomposisi, pengenalan pola, abstraksi, dan algoritma untuk menyelesaikan masalah sederhana dalam kehidupan sehari-hari. Peserta didik memahami bagaimana berpikir komputasional membantu menemukan solusi yang efektif dan efisien.'),
(17, '2026-02-27T07:45:56.079331+07:00', 'Mengenal Dunia Multimedia', 1, 6, 'Mengenalkan konsep dasar multimedia sebagai gabungan berbagai elemen digital seperti teks, gambar, audio, video, dan animasi, serta manfaatnya dalam menyampaikan informasi dan komunikasi digital secara lebih menarik dan efektif'),
(18, '2026-02-27T07:46:17.684269+07:00', 'Unsur Visual dan Audio dalam Konten Digital', 2, 6, 'Mengenalkan peran unsur visual dan audio seperti teks, gambar, warna, tata letak, dan suara dalam menarik perhatian audiens, memperjelas pesan, serta meningkatkan daya tarik konten digital'),
(19, '2026-02-27T07:46:44.565421+07:00', 'Langkah Produksi Konten Digital', 3, 6, 'Mengenalkan tahapan produksi konten digital mulai dari perencanaan ide, perancangan desain, proses pembuatan, hingga publikasi, sehingga konten yang dihasilkan terstruktur dan komunikatif'),
(20, '2026-02-27T07:47:03.761684+07:00', 'Etika dan Hak Cipta dalam Dunia Digital', 4, 6, 'Memahami pentingnya etika digital dalam berinteraksi dan berbagi konten, menghargai karya orang lain, menjaga orisinalitas, serta mencantumkan sumber referensi sebagai bentuk tanggung jawab digital'),
(21, '2026-02-27T07:47:28.836946+07:00', 'Membagikan Karya Digital (Diseminasi)', 5, 6, 'Mengenalkan cara menyebarkan konten digital melalui berbagai platform seperti blog, website, dan media sosial secara aman, efektif, dan bertanggung jawab agar informasi dapat menjangkau audiens yang tepat'),
(22, '2026-02-27T07:48:14.974262+07:00', 'Dunia Data dan Basis Data', 1, 8, 'Mengenal perbedaan data dan informasi, sumber data dalam kehidupan sehari-hari, serta memahami mengapa kecerdasan buatan membutuhkan basis data untuk bekerja secara efektif.'),
(23, '2026-02-27T07:48:33.571048+07:00', 'Struktur Basis Data', 2, 8, 'Mengenal elemen dasar basis data seperti tabel, kolom, baris (record), primary key, dan relasi antar tabel untuk menyusun data secara terstruktur.'),
(24, '2026-02-27T07:49:09.601811+07:00', 'Membuat dan Mengelola Data Sederhana', 3, 8, 'Memahami cara menambahkan, mengubah, menghapus, dan menampilkan data sebagai operasi dasar dalam pengelolaan basis data'),
(25, '2026-02-27T07:49:35.075062+07:00', 'Mengolah Data dengan Perintah Dasar', 4, 8, 'Mengenal perintah dasar pengolahan data seperti SELECT, WHERE, ORDER BY, dan GROUP BY untuk mengambil dan menyaring informasi'),
(26, '2026-02-27T07:50:04.012389+07:00', 'Menemukan Pola dari Data', 5, 8, 'Menafsirkan hasil pengolahan data untuk menemukan pola sederhana seperti nilai rata-rata, nilai maksimum, dan frekuensi kemunculan data'),
(27, '2026-02-27T07:50:28.551475+07:00', 'Practice: Analisis Data', 6, 8, 'Menggabungkan seluruh konsep dengan membuat, mengelola, dan menganalisis data sederhana untuk menghasilkan informasi yang bermakna'),
(28, '2026-02-27T07:51:20.916578+07:00', 'Apa Itu Kecerdasan Artifisial', 1, 9, 'Mengenalkan konsep dasar kecerdasan artifisial, cara kerja sederhana, serta penerapannya dalam kehidupan sehari-hari'),
(29, '2026-02-27T07:52:04.728317+07:00', 'Bagaimana AI Mengenali Pola', 2, 9, 'Mengenalkan cara AI memahami data citra dan suara, proses pelatihan model, serta faktor yang memengaruhi ketepatan hasil'),
(30, '2026-02-27T07:52:35.605678+07:00', 'Profesi di Dunia AI', 3, 9, 'Mengenalkan perubahan dunia kerja akibat AI, jenis profesi di bidang AI, keterampilan yang dibutuhkan, serta peluang karier di masa depan'),
(31, '2026-02-27T07:53:08.016625+07:00', 'Etika dan Tanggung Jawab Penggunaan AI', 4, 9, 'Memahami pentingnya etika dalam penggunaan AI, perlindungan data, potensi bias, transparansi sistem, serta tanggung jawab hukum manusia'),
(32, '2026-02-27T07:54:05.160435+07:00', 'Bagaimana AI Bisa Mencipta?', 1, 10, 'Mengenalkan konsep AI generatif sebagai bagian dari perkembangan kecerdasan artifisial yang mampu menghasilkan teks, gambar, suara, dan konten digital lainnya'),
(33, '2026-02-27T07:54:58.692913+07:00', 'Berkenalan dengan Prompt Engineering', 2, 10, 'Mengenalkan cara berinteraksi dengan AI generatif melalui perintah atau prompt. Berlatih menyusun prompt yang terarah, spesifik, dan sesuai tujuan, sehingga dapat memanfaatkan AI secara lebih efektif dan bertanggung jawab.<div><br></div>'),
(34, '2026-02-27T07:55:41.936972+07:00', 'Meningkatkan Kualitas Prompt', 3, 10, 'Mendalami prinsip penulisan prompt yang lebih efektif melalui teknik perbaikan dan penyempurnaan instruksi. Memahami pentingnya berpikir kritis dalam menilai akurasi, relevansi, dan potensi bias dari konten yang dihasilkan AI'),
(35, '2026-02-27T07:56:13.379937+07:00', 'Merancang Sistem AI Sederhana', 4, 10, 'Memperkenalkan konsep dasar AI system design melalui tahapan: identifikasi masalah, penentuan data, pemilihan model, penentuan output, serta evaluasi'),
(36, '2026-02-27T07:56:37.988978+07:00', 'Practice: Cipta Ide AI-mu Sendiri', 5, 10, 'Mengintegrasikan seluruh konsep yang telah dipelajari dengan merancang ide solusi berbasis AI untuk masalah nyata di sekitar'),
(37, '2026-02-28T14:28:17.29539+07:00', 'tes', 1, 11, 'tes')
ON CONFLICT (id) DO UPDATE SET created_at = EXCLUDED.created_at, judul = EXCLUDED.judul, bagian = EXCLUDED.bagian, id_modul = EXCLUDED.id_modul, deskripsi = EXCLUDED.deskripsi;

INSERT INTO public.latihans (id, id_pelajaran, prompt, template_code, correct_solution, points, type, data, nomor_latihan, nomor_urut, pertanyaan, unit_name, created_at) VALUES
(54, 5, '<p>Output tidak harus angka; yang penting ada hasil akhir yang jelas.</p>', NULL, NULL, 15, 'checkbox', '{"options":["Status: Lulus atau Tidak Lulus","Perasaan puas","Jumlah nilai total","Sesuatu yang dirasa cocok"],"question":"Pilih mana yang dapat menjadi output algoritma","correct_options":["Status: Lulus atau Tidak Lulus","Jumlah nilai total"]}', 2, 8, '<p><br></p>', 'Ciri Algoritma yang Baik', '2026-02-28T10:51:50.370465+07:00'),
(55, 5, '<p>Banyak aktivitas sehari-hari sebenarnya mengikuti algoritma.</p><p>Setiap aktivitas itu memiliki langkah-langkah teratur untuk mencapai tujuan.</p>', NULL, NULL, 15, 'multiple_choice', '{"correct":"Benar","options":["Benar","Salah"],"question":"“Memakai sepatu memiliki urutan langkah yang dapat dianggap sebagai algoritma.”"}', 1, 2, NULL, 'Apa itu Algoritma?', '2026-02-28T10:51:50.370465+07:00'),
(58, 5, '<p>Aktivitas sehari-hari dapat diubah menjadi algoritma hanya dengan mendeskripsikan langkah-langkahnya secara runtut.</p>', 'Contoh algoritma dalam kehidupan sehari-hari adalah proses ____ sesuatu secara ____.', 'Contoh algoritma dalam kehidupan sehari-hari adalah proses mengerjakan sesuatu secara runtut.', 15, 'fill_in_the_blank', '{"blanks":["____","____"],"options":["memilih","mengerjakan","membuat","bebas","acak","runtut"],"correct_answers":["mengerjakan","runtut"]}', 1, 3, '', 'Apa itu Algoritma?', '2026-02-28T10:51:50.370465+07:00'),
(59, 5, '<p>Sebuah algoritma harus memiliki langkah yang jelas.</p><p>Instruksi yang samar akan membuat langkah sulit dijalankan.</p>', NULL, NULL, 15, 'multiple_choice', '{"correct":"Salah","options":["Benar","Salah"],"question":"Instruksi ‘Aduk sampai terasa pas’ dapat menjadi bagian dari algoritma"}', 1, 4, '', 'Apa itu Algoritma?', '2026-02-28T10:51:50.370465+07:00'),
(60, 5, '<p>Algoritma dibuat untuk menyelesaikan masalah tertentu.</p><p>Setiap langkah mengarah pada tujuan yang ingin dicapai.</p>', 'Algoritma digunakan untuk ____ suatu masalah melalui langkah yang disusun secara ____', 'Algoritma digunakan untuk menyelesaikan suatu masalah melalui langkah yang disusun secara logis', 15, 'fill_in_the_blank', '{"blanks":["____","____"],"options":["menyelesaikan","menyususn","menemukan","logis","cepat","fleksibel"],"correct_answers":["menyelesaikan","logis"]}', 1, 5, '', 'Apa itu Algoritma?', '2026-02-28T10:51:50.370465+07:00'),
(61, 5, '<p>Tidak semua prosedur otomatis menjadi algoritma.</p><p>Prosedur yang terlalu umum atau tidak terukur tidak dianggap algoritma</p>', NULL, NULL, 15, 'drag_and_drop', '{"items":["Masukkan PIN, pilih menu, tarik uang tunai","Kerjakan seperti biasanya","Tambahkan 1 ke nilai awal hingga mencapai batas","Lakukan sesuai perasaan"],"buckets":["Algoritma","Bukan Algoritma"],"question":"<p>Pilih mana yang termasuk algoritma dan mana yang tidak</p>","correct_assignment":{"Algoritma":["Masukkan PIN, pilih menu, tarik uang tunai","Tambahkan 1 ke nilai awal hingga mencapai batas"],"Bukan Algoritma":["Kerjakan seperti biasanya","Lakukan sesuai perasaan"]}}', 1, 6, '<p><br></p>', 'Apa itu Algoritma?', '2026-02-28T10:51:50.370465+07:00'),
(62, 5, '<p>Program komputer adalah bentuk implementasi dari algoritma.</p><p>Algoritma dibuat terlebih dahulu sebelum program disusun</p>', NULL, NULL, 15, 'drag_and_drop', '{"items":["Implementasi langkah-langkah tersebut dalam bahasa pemrograman","Rangkaian langkah logis untuk menyelesaikan masalah"],"buckets":["Algoritma","Program"],"question":"<p>Cocokkan istilah berikut dengan penjelasannya</p>","correct_assignment":{"Program":["Implementasi langkah-langkah tersebut dalam bahasa pemrograman"],"Algoritma":["Rangkaian langkah logis untuk menyelesaikan masalah"]}}', 1, 7, '<p><br></p>', 'Apa itu Algoritma?', '2026-02-28T10:51:50.370465+07:00'),
(63, 5, '<p>Algoritma membantu memecah masalah menjadi langkah-langkah kecil yang mudah dijalankan</p>', NULL, NULL, 15, 'multiple_choice', '{"correct":"Tambahkan 2 ke nilai awal hingga mencapai 20","options":["Kerjakan sesuai perasaan","Tambahkan 2 ke nilai awal hingga mencapai 20","Lakukan seadanya","Tekan tombol jika perlu"],"question":"Pilih yang termasuk langkah algoritmik"}', 1, 8, '<p><br></p>', 'Apa itu Algoritma?', '2026-02-28T10:51:50.370465+07:00'),
(64, 5, '<p>Algoritma yang baik memiliki instruksi yang jelas sehingga tidak menimbulkan lebih dari satu interpretasi</p>', NULL, NULL, 15, 'multiple_choice', '{"correct":"Salah","options":["Benar","Salah"],"question":"Instruksi ‘aduk sampai pas’ dapat dianggap jelas dalam sebuah algoritma"}', 2, 1, '<p><br></p>', 'Ciri Algoritma yang Baik', '2026-02-28T10:51:50.370465+07:00'),
(65, 5, '<p>Kejelasan instruksi memastikan setiap orang mengeksekusi langkah yang sama. Semakin spesifik, semakin baik</p>', NULL, NULL, 15, 'multiple_choice', '{"correct":"Tambahkan 200 ml air panas","options":["Tambahkan air secukupnya","Tambahkan air bila perlu","Tambahkan 200 ml air panas","Tambahkan air sampai dirasa cukup"],"question":"Manakah instruksi yang paling jelas?"}', 2, 2, '', 'Ciri Algoritma yang Baik', '2026-02-28T10:51:50.370465+07:00'),
(66, 5, '<p>Algoritma yang baik harus memiliki akhir.</p><p>Jika langkah berjalan tanpa batas, algoritma tidak dapat diselesaikan</p>', NULL, NULL, 15, 'multiple_choice', '{"correct":"Salah","options":["Benar","Salah"],"question":"Langkah ‘ulangi terus tanpa berhenti’ termasuk contoh algoritma"}', 2, 3, '', 'Ciri Algoritma yang Baik', '2026-02-28T10:51:50.370465+07:00'),
(67, 5, '<p>Sebuah algoritma boleh memiliki pengulangan, tetapi syarat berhentinya harus jelas.</p>', NULL, NULL, 15, 'multiple_choice', '{"correct":"Ulangi sampai nilai menjadi 0","options":["Ulangi sampai sesuai","Ulangi sampai hasil memuaskan","Ulangi selama masih bisa","Ulangi sampai nilai menjadi 0"],"question":"Manakah contoh kondisi berhenti yang jelas?"}', 2, 4, '', 'Ciri Algoritma yang Baik', '2026-02-28T10:51:50.370465+07:00'),
(68, 5, '<p>Langkah dalam algoritma harus dapat dilakukan dan dapat dihitung.</p><p>Jika langkah tidak dapat dieksekusi, algoritma menjadi tidak efektif</p>', 'Langkah harus dapat dijalankan agar algoritma dianggap ____.', 'Langkah harus dapat dijalankan agar algoritma dianggap efektif.', 15, 'fill_in_the_blank', '{"blanks":["____"],"options":["fleksibel","cepat","efektif","bebas"],"correct_answers":["efektif"]}', 2, 5, '<p><br></p>', 'Ciri Algoritma yang Baik', '2026-02-28T10:51:50.370465+07:00'),
(69, 5, '<p>Efektivitas berarti setiap langkah dapat dieksekusi dengan sumber daya yang wajar.</p>', NULL, NULL, 15, 'multiple_choice', '{"correct":"Hitung jumlah seluruh kemungkinan bilangan sampai tak hingga","options":["Hitung rata-rata dari daftar nilai","Kalikan angka dengan 0","Hitung jumlah seluruh kemungkinan bilangan sampai tak hingga","Tambahkan 1 ke nilai awal"],"question":"Manakah langkah yang tidak efektif?"}', 2, 6, '', 'Ciri Algoritma yang Baik', '2026-02-28T10:51:50.370465+07:00'),
(70, 5, '<p>Algoritma harus menghasilkan sesuatu, baik keputusan, nilai, atau perubahan keadaan.</p><p>Tanpa output, tujuan algoritma tidak tercapai.</p>', NULL, NULL, 15, 'multiple_choice', '{"correct":"Salah","options":["Benar","Salah"],"question":"Algoritma tanpa hasil akhir tetap dapat dianggap algoritma"}', 2, 7, '', 'Ciri Algoritma yang Baik', '2026-02-28T10:51:50.370465+07:00'),
(71, 5, '<p>Algoritma adalah serangkaian langkah yang teratur untuk menyelesaikan sebuah masalah.</p><p>Tanpa urutan yang jelas, langkah-langkah itu tidak dapat disebut algoritma</p>', NULL, NULL, 15, 'multiple_choice', '{"correct":"Serangkaian instruksi teratur untuk mencapai hasil tertentu","options":["Langkah-langkah yang dapat dijalankan dalam urutan apa pun","Serangkaian instruksi teratur untuk mencapai hasil tertentu","Semua perintah yang dijalankan komputer","Kumpulan langkah tanpa aturan khusus"],"question":"Manakah definisi algoritma yang paling tepat?"}', 1, 1, '', 'Apa itu Algoritma?', '2026-02-28T10:51:50.370465+07:00'),
(72, 5, '<p>Komputer bekerja dengan mengikuti instruksi secara tepat.</p><p>Algoritma menentukan urutan instruksi tersebut</p>', NULL, NULL, 15, 'multiple_choice', '{"correct":"Salah","options":["Benar","Salah"],"question":"Komputer dapat menebak langkah yang tidak ditulis pada algoritma"}', 3, 1, '', 'Peran Algoritma dalam Komputer', '2026-02-28T10:51:50.370465+07:00'),
(73, 5, '<p>Sebelum sebuah program dijalankan komputer, algoritma harus dibuat terlebih dahulu.</p><p>Algoritma menjadi dasar logika program</p>', 'Sebuah program dibuat berdasarkan ____, lalu dijalankan oleh ____.', 'Sebuah program dibuat berdasarkan Algoritma, lalu dijalankan oleh komputer.', 15, 'fill_in_the_blank', '{"blanks":["____","____"],"options":["Algoritma","data pengguna","komputer"],"correct_answers":["Algoritma","komputer"]}', 3, 2, '', 'Peran Algoritma dalam Komputer', '2026-02-28T10:51:50.370465+07:00'),
(74, 5, '<p>Komputer menjalankan instruksi secara berurutan dari awal hingga akhir.</p><p>Urutan yang salah membuat program tidak berjalan benar</p>', NULL, NULL, 15, 'multiple_choice', '{"correct":"Mengeksekusi instruksi baris demi baris","options":["Mengeksekusi instruksi baris demi baris","Menebak hasil akhir","Melompati bagian yang dianggap tidak perlu","Mengubah langkah jika merasa perlu"],"question":"Pilih langkah yang menunjukkan bahwa komputer mengikuti urutan"}', 3, 3, '', 'Peran Algoritma dalam Komputer', '2026-02-28T10:51:50.370465+07:00'),
(75, 5, '<p>Algoritma menjelaskan logika yang harus diikuti komputer.</p><p>Komputer hanya menjalankan, bukan memahami tujuan</p>', 'Komputer ____ instruksi, bukan ____ maksudnya, sehingga algoritma harus dibuat ____.', 'Komputer mengikuti instruksi, bukan memahami maksudnya, sehingga algoritma harus dibuat jelas.', 15, 'fill_in_the_blank', '{"blanks":["____","____","____"],"options":["menduga","mengikuti","memahami","jelas","acak"],"correct_answers":["mengikuti","memahami","jelas"]}', 3, 4, '', 'Peran Algoritma dalam Komputer', '2026-02-28T10:51:50.370465+07:00'),
(76, 5, '<p>Algoritma membantu komputer mengambil keputusan berdasarkan kondisi.</p><p>Tanpa algoritma, komputer tidak tahu apa yang harus dilakukan.</p>', NULL, NULL, 15, 'multiple_choice', '{"correct":"Salah","options":["Benar","Salah"],"question":"\"Komputer dapat memilih tindakan terbaik tanpa algoritma\""}', 3, 5, '', 'Peran Algoritma dalam Komputer', '2026-02-28T10:51:50.370465+07:00'),
(77, 5, '<p>Program hanya bekerja dengan baik jika algoritma disusun dengan benar. Kesalahan algoritma akan membuat program salah meski kodenya benar.</p>', 'Jika algoritma salah, maka ____ akan menghasilkan output yang ____.', 'Jika algoritma salah, maka program akan menghasilkan output yang tidak tepat.', 15, 'fill_in_the_blank', '{"blanks":["____","____"],"options":["program","tidak tepat","cepat","komputer"],"correct_answers":["program","tidak tepat"]}', 3, 6, '', 'Peran Algoritma dalam Komputer', '2026-02-28T10:51:50.370465+07:00'),
(78, 5, '<p>Algoritma membuat komputer dapat menyelesaikan tugas berulang secara konsisten.</p><p>Tanpa algoritma, komputer tidak memiliki pola kerja.</p>', NULL, NULL, 15, 'multiple_choice', '{"correct":"Salah","options":["Benar","Salah"],"question":"\"Komputer bisa menjalankan tugas yang sama setiap hari tanpa algoritma\""}', 3, 7, '', 'Peran Algoritma dalam Komputer', '2026-02-28T10:51:50.370465+07:00'),
(79, 5, '<p>Algoritma adalah inti dari seluruh proses pemrograman.</p><p>Program hanyalah bentuk algoritma yang sudah diterjemahkan ke kode.</p>', 'Algoritma menjadi ____ dari program, karena program ____ langkah-langkah tersebut dalam bentuk ____.', 'Algoritma menjadi dasar dari program, karena program menerjemahkan langkah-langkah tersebut dalam bentuk kode.', 15, 'fill_in_the_blank', '{"blanks":["____","____","____"],"options":["gambaran","dasar","kode","data","menerjemahkan"],"correct_answers":["dasar","menerjemahkan","kode"]}', 3, 8, '', 'Peran Algoritma dalam Komputer', '2026-02-28T10:51:50.370465+07:00'),
(80, 6, '<p>Narasi algoritma adalah cara menuliskan langkah-langkah menggunakan kalimat sederhana yang dapat dibaca manusia</p>', NULL, NULL, 15, 'multiple_choice', '{"correct":"Panaskan air → Masukkan mie → Tambahkan bumbu → Aduk","options":["Air mendidih lebih cepat jika memakai panci kecil","Panaskan air → Masukkan mie → Tambahkan bumbu → Aduk"],"question":"Manakah yang merupakan contoh narasi algoritma"}', 1, 1, '', 'Bentuk Narasi', '2026-02-28T10:51:50.370465+07:00'),
(81, 6, '<p>Sebuah narasi algoritma harus memiliki urutan langkah yang logis dan runtut</p>', NULL, NULL, 15, 'sorting', '{"question":"Urutkan langkah-langkah berikut agar langkah yang benar","code_lines":["Keringkan tangan","Gosok tangan dengan sabun","Bilas tangan dengan air bersih","Basahi tangan dengan air"],"correct_order":["Basahi tangan dengan air","Gosok tangan dengan sabun","Bilas tangan dengan air bersih","Keringkan tangan"]}', 1, 2, '<p>Urutkan langkah-langkah berikut agar langkah yang benar</p>', 'Bentuk Narasi', '2026-02-28T10:51:50.370465+07:00'),
(82, 6, '<p>Narasi algoritma yang baik harus jelas dan tidak membingungkan.</p>', NULL, NULL, 15, 'checkbox', '{"options":["Masukkan pakaian ke mesin cuci","Pakaian yang bersih lebih wangi","Tambahkan deterjen","Nyalakan mesin cuci"],"question":"Pilih semua langkah yang merupakan langkah algoritmik","correct_options":["Masukkan pakaian ke mesin cuci","Tambahkan deterjen","Nyalakan mesin cuci"]}', 1, 3, '', 'Bentuk Narasi', '2026-02-28T10:51:50.370465+07:00'),
(83, 6, '<p>Langkah algoritma harus berupa aksi yang dapat dilakukan</p>', NULL, NULL, 15, 'drag_and_drop', '{"items":["Potong sayuran","Sayuran mengandung vitamin","Kesehatan itu penting","Masukkan sayuran ke panci"],"buckets":["Langkah Algoritma","Bukan Langkah"],"question":"<p>Kelompokkan langkah berikut ke kategori yang tepat</p>","correct_assignment":{"Bukan Langkah":["Sayuran mengandung vitamin","Kesehatan itu penting"],"Langkah Algoritma":["Potong sayuran","Masukkan sayuran ke panci"]}}', 1, 4, '<p><br></p>', 'Bentuk Narasi', '2026-02-28T10:51:50.370465+07:00'),
(84, 6, '<p>Narasi algoritma sering digunakan sebelum membuat pseudocode atau flowchart.</p>', 'Algoritma dalam bentuk ____ membantu kita memahami alur sebelum menuliskannya ke bentuk yang lebih formal.', 'Algoritma dalam bentuk narasi membantu kita memahami alur sebelum menuliskannya ke bentuk yang lebih formal.', 15, 'fill_in_the_blank', '{"blanks":["____"],"options":["flowchart","narasi","pseudocode"],"correct_answers":["narasi"]}', 1, 5, '', 'Bentuk Narasi', '2026-02-28T10:51:50.370465+07:00'),
(85, 6, '<p>Satu kesalahan kecil dalam urutan langkah dapat membuat hasil akhir tidak sesuai</p>', NULL, NULL, 15, 'multiple_choice', '{"correct":"Buka layar → Tekan tombol power → Tunggu menyala","options":["Buka layar → Tekan tombol power → Tunggu menyala","Tekan tombol power → Colok charger → Tempelkan stiker laptop"],"question":"Manakah yang paling benar untuk menyalakan laptop?"}', 1, 6, '', 'Bentuk Narasi', '2026-02-28T10:51:50.370465+07:00'),
(86, 6, '<p>Narasi algoritma yang baik menggunakan kata kerja yang konsisten agar mudah diubah ke bentuk pseudocode.</p>', NULL, NULL, 15, 'multiple_choice', '{"correct":"Masukkan angka pertama. Masukkan angka kedua. Jumlahkan kedua angka. Tampilkan hasil.","options":["Ambil buku. Buku itu penting untuk belajar. Belajar membuat pintar.","Masukkan angka pertama. Masukkan angka kedua. Jumlahkan kedua angka. Tampilkan hasil.","Angka adalah sesuatu yang bisa dihitung. Menjumlahkan itu mudah. Hasilnya menyenangkan."],"question":"Mana narasi algoritma yang benar?"}', 1, 7, '', 'Bentuk Narasi', '2026-02-28T10:51:50.370465+07:00'),
(87, 6, '<p>Pseudocode adalah cara menuliskan algoritma dengan bentuk mirip kode, tetapi tetap mudah dibaca manusia dan tidak terikat bahasa pemrograman tertentu</p>', NULL, NULL, 15, 'multiple_choice', '{"correct":"Langkah-langkah algoritma dalam bentuk mirip kode namun tidak bergantung bahasa pemrograman","options":["Bahasa pemrograman resmi","Diagram untuk memvisualisasikan proses","Kode Python yang disederhanakan","Langkah-langkah algoritma dalam bentuk mirip kode namun tidak bergantung bahasa pemrograman"],"question":"Manakah pernyataan yang paling tepat tentang pseudocode?"}', 2, 1, '', 'Pseudocode', '2026-02-28T10:51:50.370465+07:00'),
(88, 6, '<p>Pseudocode mempermudah pemrogram melihat alur logika tanpa terganggu aturan sintaks. Dengan pseudocode, kesalahan logika dapat ditemukan lebih awal.</p>', NULL, NULL, 15, 'drag_and_drop', '{"items":["Tidak terikat sintaks","Logika sudah jelas sebelum ditulis menjadi kode","Penjelasan langkah dituliskan secara sederhana"],"buckets":["Lebih mudah dibaca","Mengurangi error saat coding","Membantu fokus pada logika"],"question":"<p>Cocokkan manfaat dengan alasannya</p>","correct_assignment":{"Lebih mudah dibaca":["Penjelasan langkah dituliskan secara sederhana"],"Membantu fokus pada logika":["Tidak terikat sintaks"],"Mengurangi error saat coding":["Logika sudah jelas sebelum ditulis menjadi kode"]}}', 2, 2, '<p><br></p>', 'Pseudocode', '2026-02-28T10:51:50.370465+07:00'),
(89, 6, '<p>Struktur dasar pseudocode biasanya terdiri dari</p><p>START / BEGIN, Deklarasi &amp; input, Proses, Output, END</p>', NULL, NULL, 15, 'sorting', '{"question":"Urutkan struktur pseudocode berikut","code_lines":["Proses","End","Output","Input","Start"],"correct_order":["Start","Input","Proses","Output","End"]}', 2, 3, '', 'Pseudocode', '2026-02-28T10:51:50.370465+07:00'),
(90, 6, '<p>Aturan penulisan pseudocode yang umum digunakan:</p><p>- Menggunakan bahasa yang jelas dan konsisten</p><p>- Setiap langkah ditulis pada baris baru</p><p>- Indentasi untuk menandai blok perintah</p><p>- Gunakan kata kunci standar (READ, PRINT, IF, WHILE, dsb.)</p>', NULL, NULL, 15, 'checkbox', '{"options":["Setiap langkah ditulis pada baris baru","Menggunakan bahasa sehari-hari yang acak","Menggunakan indentasi","Harus menggunakan bahasa Inggris saja"],"question":"Yang merupakan aturan penulisan pseudocode adalah","correct_options":["Setiap langkah ditulis pada baris baru","Menggunakan indentasi"]}', 2, 4, '', 'Pseudocode', '2026-02-28T10:51:50.370465+07:00'),
(91, 6, '<p>Pseudocode tersusun atas judul, deklarasi variabel, dan langkah algoritma (input–proses–output).</p>', NULL, NULL, 15, 'drag_and_drop', '{"items":["A, B, Hasil : Integer","input(A)","input(B)","output(Hasil)","Hasil = A + B","Algoritma Penjumlahan"],"buckets":["Judul","Deklarasi","Deskripsi algoritma"],"question":"<p>Cocokkan bagian-bagian struktur algoritma dengan potongan pseudocode yang sesuai</p>","correct_assignment":{"Judul":["Algoritma Penjumlahan"],"Deklarasi":["A, B, Hasil : Integer"],"Deskripsi algoritma":["input(A)","input(B)","output(Hasil)","Hasil = A + B"]}}', 2, 5, '<p>Cocokkan bagian-bagian struktur algoritma dengan potongan pseudocode yang sesuai</p>', 'Pseudocode', '2026-02-28T10:51:50.370465+07:00'),
(92, 6, '<p>Pseudocode menggunakan kata kunci khusus untuk menandai jenis langkah</p>', NULL, NULL, 15, 'drag_and_drop', '{"items":["END","PRINT","READ","IF-THEN"],"buckets":["Kata kunci untuk input","Kata kunci untuk output","Digunakan untuk blok keputusan","Mengakhiri pseudocode"],"question":"<p>Cocokan fungsi dan kata kuncinya</p>","correct_assignment":{"Mengakhiri pseudocode":["END"],"Kata kunci untuk input":["READ"],"Kata kunci untuk output":["PRINT"],"Digunakan untuk blok keputusan":["IF-THEN"]}}', 2, 6, '<p>Cocokan fungsi dan kata kuncinya</p>', 'Pseudocode', '2026-02-28T10:51:50.370465+07:00'),
(93, 6, '<p>Bagian proses berisi operasi atau rumus yang mengolah data input untuk menghasilkan output.</p>', 'START
READ sisi
keliling ← ____ * sisi
PRINT keliling
END', 'START
READ sisi
keliling ← 4 * sisi
PRINT keliling
END', 15, 'fill_in_the_blank', '{"blanks":["____"],"options":["4","sisi","panjang","lebar","2"],"correct_answers":["4"]}', 2, 7, '<p>Lengkapi pseudocode berikut</p>', 'Pseudocode', '2026-02-28T10:51:50.370465+07:00'),
(94, 6, '<p>Pseudocode harus memiliki urutan logis dan penempatan input sebelum proses.</p>', NULL, NULL, 15, 'multiple_choice', '{"correct":"START\nREAD umur\nIF umur >= 17 THEN\nPRINT \"Dewasa\"\nELSE\nPRINT \"Belum dewasa\"\nEND","options":["START\nPRINT \"dewasa\"\nREAD umur\nIF umur >= 17 THEN\nEND","START\nREAD umur\nIF umur >= 17 THEN\nPRINT \"Dewasa\"\nELSE\nPRINT \"Belum dewasa\"\nEND","START\nIF umur >= 17 THEN\nREAD umur\nPRINT \"Dewasa\"\nEND"],"question":"Manakah pseudocode yang benar untuk “Menentukan apakah umur ≥ 17\t”"}', 2, 8, '<p>Manakah pseudocode yang benar untuk “Menentukan apakah umur ≥ 17"</p>', 'Pseudocode', '2026-02-28T10:51:50.370465+07:00'),
(95, 6, '<p>Flowchart adalah representasi visual algoritma menggunakan simbol standar untuk menunjukkan alur langkah secara jelas.</p>', NULL, NULL, 15, 'multiple_choice', '{"correct":"Menampilkan algoritma secara visual","options":["Menjalankan program langsung","Menampilkan algoritma secara visual","Mengganti bahasa pemrograman","Menghitung output secara otomatis"],"question":"Flowchart digunakan untuk…"}', 3, 1, '', 'Flowchart', '2026-02-28T10:51:50.370465+07:00'),
(96, 6, '<p>Setiap simbol flowchart memiliki fungsi khusus agar alur mudah dibaca dan tidak ambigu</p>', NULL, NULL, 15, 'multiple_choice', '{"correct":"Awal dan akhir alur","options":["Proses perhitungan","Input dan output","Percabangan","Awal dan akhir alur"],"question":"Simbol oval pada flowchart digunakan untuk…"}', 3, 2, '', 'Flowchart', '2026-02-28T10:51:50.370465+07:00'),
(97, 6, '<p>Simbol persegi panjang digunakan untuk langkah proses atau perhitungan.</p>', NULL, NULL, 15, 'multiple_choice', '{"correct":"total ← harga × jumlah","options":["READ nilai","IF nilai ≥ 75","total ← harga × jumlah","PRINT hasil"],"question":"Manakah yang paling tepat ditulis dalam persegi panjang?"}', 3, 3, '', 'Flowchart', '2026-02-28T10:51:50.370465+07:00'),
(98, 6, '<p>Simbol jajar genjang digunakan untuk menerima input atau menampilkan output.</p>', NULL, NULL, 15, 'checkbox', '{"options":["READ umur","PRINT hasil","total ← a + b","IF nilai ≥ 60"],"question":"Pilih semua yang menggunakan simbol jajar genjang","correct_options":["READ umur","PRINT hasil"]}', 3, 4, '', 'Flowchart', '2026-02-28T10:51:50.370465+07:00'),
(99, 10, '<p>Debugging adalah proses mencari dan memperbaiki kesalahan dalam program.</p>', NULL, NULL, 10, 'multiple_choice', '{"correct":"Tidak bisa dijalankan atau hasilnya salah","options":["Sudah benar","Tidak bisa dijalankan atau hasilnya salah","Baru selesai ditulis","Sudah diupload"],"question":"Debugging dilakukan ketika program…"}', 1, 1, '<p>Debugging dilakukan ketika program…</p>', 'Apa itu Debugging?', '2026-02-28T10:51:50.370465+07:00'),
(100, 10, 'Kesalahan dalam program disebut bug.', 'Debugging adalah proses mencari dan memperbaiki ____ dalam sebuah program.', 'bug', 10, 'fill_in_the_blank', '{"blanks":["____"],"options":["bug","variabel","output","data"],"correct_answers":["bug"]}', 1, 2, 'Lengkapi kalimat berikut:', 'Apa itu Debugging?', '2026-02-28T10:51:50.370465+07:00'),
(101, 10, '<p>Bug bisa muncul karena logika yang salah.</p>', NULL, NULL, 10, 'multiple_choice', '{"correct":"Operator salah","options":["Tidak ada bug","Operator salah","Variabel salah","Urutan salah"],"question":"Jawablah pertanyaan ini:"}', 1, 3, '<p>Perhatikan kode berikut:</p><pre class="ql-syntax" spellcheck="false">x = 10
y = 5
print(x - y). 
</pre><p>Program ingin menjumlahkan x dan y. Apa masalahnya?</p>', 'Apa itu Debugging?', '2026-02-28T10:51:50.370465+07:00'),
(102, 10, 'Debugging dilakukan secara bertahap dan terstruktur.', NULL, NULL, 10, 'sorting', '{"code_lines":["Menemukan sumber kesalahan","Memperbaiki kesalahan","Mengetes hasil program","Menjalankan ulang program"],"correct_order":["Menemukan sumber kesalahan","Memperbaiki kesalahan","Mengetes hasil program","Menjalankan ulang program"]}', 1, 4, 'Urutkan langkah debugging berikut agar benar:', 'Apa itu Debugging?', '2026-02-28T10:51:50.370465+07:00'),
(103, 10, 'Bug juga bisa terjadi karena struktur kode tidak lengkap.', 'if x > 5:\n    ____("x lebih besar dari 5")', 'print', 10, 'fill_in_the_blank', '{"blanks":["____"],"options":["print","input","return","show"],"correct_answers":["print"]}', 1, 5, 'Lengkapi kode berikut agar perintah print berjalan benar:', 'Apa itu Debugging?', '2026-02-28T10:51:50.370465+07:00'),
(104, 10, 'Tidak semua aktivitas adalah debugging.', NULL, NULL, 10, 'drag_and_drop', '{"items":["Memperbaiki tanda kurung yang salah","Mencari baris kode yang error","Menjalankan program tanpa melihat hasil","Menulis program baru dari awal"],"buckets":["Debugging","Bukan Debugging"],"correct_assignment":{"Debugging":["Memperbaiki tanda kurung yang salah","Mencari baris kode yang error"],"Bukan Debugging":["Menjalankan program tanpa melihat hasil","Menulis program baru dari awal"]}}', 1, 6, 'Kelompokkan aktivitas berikut:', 'Apa itu Debugging?', '2026-02-28T10:51:50.370465+07:00'),
(105, 10, '<p>Kode yang tidak berurutan bisa menyebabkan error.</p>', NULL, NULL, 10, 'sorting', '{"code_lines":["print(\"Selesai\")","if x > 5:"],"correct_order":["if x > 5:","print(\"Selesai\")"]}', 1, 7, '<p>Urutkan baris kode berikut agar menjadi struktur logika yang benar:</p>', 'Apa itu Debugging?', '2026-02-28T10:51:50.370465+07:00'),
(106, 10, 'Bug bisa berasal dari berbagai penyebab.', NULL, NULL, 10, 'drag_and_drop', '{"items":["Output tidak sesuai","Program tidak bisa dijalankan","Variabel belum didefinisikan","Program berjalan normal"],"buckets":["Bug","Bukan Bug"],"correct_assignment":{"Bug":["Output tidak sesuai","Program tidak bisa dijalankan","Variabel belum didefinisikan"],"Bukan Bug":["Program berjalan normal"]}}', 1, 8, 'Kelompokkan masalah berikut:', 'Apa itu Debugging?', '2026-02-28T10:51:50.370465+07:00'),
(107, 10, 'Debugging adalah bagian penting dari proses pemrograman.', NULL, NULL, 10, 'multiple_choice', '{"correct":"Memperbaiki kesalahan agar program berjalan benar","options":["Menulis ulang seluruh program","Menghancurkan kode","Memperbaiki kesalahan agar program berjalan benar","Menghilangkan semua variabel"],"question":"Tujuan utama debugging adalah…"}', 1, 9, 'Tujuan utama debugging adalah…', 'Apa itu Debugging?', '2026-02-28T10:51:50.370465+07:00'),
(108, 10, '<p>Syntax Error adalah kesalahan penulisan aturan bahasa pemrograman sehingga program tidak bisa dijalankan.</p>', NULL, NULL, 10, 'multiple_choice', '{"correct":"Program berhenti sebelum dijalankan","options":["Hasil perhitungan salah","Program berhenti sebelum dijalankan","Logika salah menentukan kondisi","Variabel bernilai salah"],"question":"Manakah yang termasuk syntax error?"}', 2, 1, '<p>Manakah yang termasuk syntax error?</p>', 'Jenis Error: Syntax vs Logic', '2026-02-28T10:51:50.370465+07:00'),
(109, 10, '<p>Syntax Error membuat kode tidak bisa dijalankan, biasanya karena aturan bahasa dilanggar.</p>', '<p>Ini adalah paragraf____\n', '<p>Ini adalah paragraf</p>\n', 10, 'fill_in_the_blank', '{"blanks":["____"],"options":["</p>","<p>","</div>"],"correct_answers":["</p>"]}', 2, 2, '<p>Lengkapi kode berikut agar tidak terjadi syntax error.</p>', 'Jenis Error: Syntax vs Logic', '2026-02-28T10:51:50.370465+07:00'),
(110, 10, 'Logic Error adalah kesalahan cara berpikir atau alur logika, program tetap jalan tapi hasilnya tidak sesuai harapan.', NULL, NULL, 10, 'multiple_choice', '{"correct":"Program berjalan tapi hasil salah","options":["Program tidak bisa dijalankan","Muncul pesan error","Program berjalan tapi hasil salah","Kode tidak bisa dikompilasi"],"question":"Ciri utama logic error adalah…"}', 2, 3, 'Ciri utama logic error adalah…', 'Jenis Error: Syntax vs Logic', '2026-02-28T10:51:50.370465+07:00'),
(111, 10, '<p>Logic Error muncul ketika program berjalan tapi hasilnya tidak sesuai harapan, misalnya operator salah.</p>', 'let a = 5;\nlet b = 3;\nconsole.log(a - b);

Kode di atas bertujuan menjumlahkan a dan b. Kesalahan pada kode tersebut adalah ____.', 'let a = 5;\nlet b = 3;\nconsole.log(a - b);

Kode di atas bertujuan menjumlahkan a dan b. Kesalahan pada kode tersebut adalah logic error.', 10, 'fill_in_the_blank', '{"blanks":["____"],"options":["syntax error","runtime error","logic error"],"correct_answers":["logic error"]}', 2, 4, '<p><br></p>', 'Jenis Error: Syntax vs Logic', '2026-02-28T10:51:50.370465+07:00'),
(112, 10, 'Mengetahui jenis error membantu proses debugging lebih cepat.', NULL, NULL, 10, 'drag_and_drop', '{"items":["Kurang tanda }","Tag <p> tidak ditutup","Salah operasi perbandingan","Salah operasi hitung"],"buckets":["Syntax Error","Logic Error"],"correct_assignment":{"Logic Error":["Salah operasi perbandingan","Salah operasi hitung"],"Syntax Error":["Kurang tanda }","Tag <p> tidak ditutup"]}}', 2, 5, 'Kelompokkan contoh berikut ke jenis error yang benar.', 'Jenis Error: Syntax vs Logic', '2026-02-28T10:51:50.370465+07:00'),
(113, 10, 'Saat menemukan error, ada urutan langkah yang efektif untuk debugging: baca pesan error → temukan baris bermasalah → perbaiki → jalankan ulang.', NULL, NULL, 10, 'sorting', '{"code_lines":["Membaca pesan error","Menemukan baris kode bermasalah","Memperbaiki kode","Menjalankan ulang program"],"correct_order":["Membaca pesan error","Menemukan baris kode bermasalah","Memperbaiki kode","Menjalankan ulang program"]}', 2, 6, 'Urutkan langkah berikut agar debugging efektif:', 'Jenis Error: Syntax vs Logic', '2026-02-28T10:51:50.370465+07:00'),
(114, 10, 'Logic error bisa muncul walaupun kode bisa dijalankan, misalnya kondisi IF salah sehingga output tidak sesuai.', 'let nilai = 80;\n\nif (nilai > 90) {\n  console.log("Lulus");\n} else {\n  console.log("Tidak Lulus");\n}', 'Logic Error', 10, 'multiple_choice', '{"correct":"Logic Error","options":["Syntax Error","Logic Error","Runtime Error","Tidak ada error"],"question":"Program di atas tidak menampilkan hasil yang diharapkan. Jenis error apakah ini?"}', 2, 7, 'Program di atas tidak menampilkan hasil yang diharapkan. Jenis error apakah ini?', 'Jenis Error: Syntax vs Logic', '2026-02-28T10:51:50.370465+07:00'),
(115, 10, '<p>Memahami perbedaan syntax dan logic error membantu memutuskan langkah perbaikan yang tepat.</p>', NULL, NULL, 10, 'multiple_choice', '{"correct":"Logic error; periksa operator dan ubah sesuai tujuan","options":["Syntax error; jalankan ulang program","Logic error; periksa operator dan ubah sesuai tujuan","Runtime error; definisikan variabel baru","Tidak ada error; output sudah benar"],"question":"Apa jenis error dan bagaimana langkah pertama yang tepat?"}', 2, 8, '<p><span style="background-color: transparent; color: rgb(0, 0, 0);">Kode berikut ingin menampilkan jumlah dua angka.</span></p><pre class="ql-syntax" spellcheck="false">let x = 4;
let y = 5;
console.log(x * y);
</pre><p>Apa jenis error dan bagaimana langkah pertama yang tepat?</p>', 'Jenis Error: Syntax vs Logic', '2026-02-28T10:51:50.370465+07:00'),
(116, 10, '<p>Debugging dimulai dengan menyadari bahwa ada kesalahan dalam kode.</p>', NULL, NULL, 10, 'multiple_choice', '{"correct":"Mengetahui letak kesalahan","options":["Membuat kode lebih panjang","Mengetahui letak kesalahan","Menghapus semua kode","Menjalankan kode lebih cepat"],"question":"Tujuan utama dari mengenali error adalah…"}', 3, 1, '<p>Tujuan utama dari mengenali error adalah…</p>', 'Mengenali error dalam kode', '2026-02-28T10:51:50.370465+07:00'),
(117, 10, '<p>Syntax error terjadi karena aturan bahasa pemrograman dilanggar.</p>', NULL, NULL, 10, 'multiple_choice', '{"correct":"Tanda kurung penutup","options":["console","log","Tanda kurung penutup","Tanda titik koma"],"question":"Error terdapat pada bagian…"}', 3, 2, '<p>Error terdapat pada bagian…</p>', 'Mengenali error dalam kode', '2026-02-28T10:51:50.370465+07:00'),
