(143, 10, 'FOR loop mengulang berdasarkan jumlah elemen atau rentang tertentu.', 'for i in range(2, 6):\n    print(i)', '2', 10, 'multiple_choice', '{"correct":"2","options":["1","2","6","5"],"question":"Output pertama yang muncul adalah…"}', 5, 6, 'Output pertama yang muncul adalah…', 'Menentukan Output', '2026-02-28T10:51:50.370465+07:00'),
