(179, 6, '<p>Setiap perintah dalam pseudocode memiliki padanan simbol flowchart.</p>', NULL, NULL, 15, 'multiple_choice', '{"correct":"Jajar genjang → Persegi panjang → Jajar genjang","options":["Jajar genjang → Persegi panjang → Jajar genjang","Oval → Jajar genjang → Persegi panjang","Persegi panjang → Belah ketupat → Oval","Oval → Persegi panjang → Oval"],"question":"-"}', 4, 4, '<p>READ nilai</p><p>hasil ← nilai + 5</p><p>PRINT hasil</p><p><br></p><p>Simbol flowchart yang digunakan berturut-turut adalah</p>', 'Konversi Representasi Algoritma', '2026-02-28T10:51:50.370465+07:00'),
(180, 6, '<p>Struktur IF pada pseudocode selalu diterjemahkan menjadi simbol decision.</p>', 'IF umur >= 17 THEN
    PRINT "Dewasa"
