(184, 7, '<p>Struktur kontrol adalah cara mengatur alur langkah algoritma, bukan sekadar menulis langkah.</p>', NULL, NULL, 15, 'multiple_choice', '{"correct":"Mengatur urutan eksekusi","options":["Menyimpan data","Menampilkan output","Mengubah tipe data","Mengatur urutan eksekusi"],"question":"-"}', 1, 1, '<p>Struktur kontrol digunakan untuk...</p>', 'Konsep Struktur Kontrol', '2026-02-28T10:51:50.370465+07:00'),
(185, 7, '<p>Semua algoritma dibangun dari alur lurus (sequence), pilihan (selection), dan pengulangan (looping)</p>', NULL, NULL, 15, 'drag_and_drop', '{"items":["Percabangan kondisi (IF)","pengulangan langkah","Langkah berurutan"],"buckets":["Sequence","Selection","Looping"],"question":"<p><br></p>","correct_assignment":{"Looping":["pengulangan langkah"],"Sequence":["Langkah berurutan"],"Selection":["Percabangan kondisi (IF)"]}}', 1, 2, '<p>Cocokkan struktur kontrol dan fungsinya</p>', 'Konsep Struktur Kontrol', '2026-02-28T10:51:50.370465+07:00'),
(186, 7, '<p>Satu algoritma dapat mengandung satu atau lebih jenis struktur kontrol, tergantung pada kebutuhan alurnya.</p>', NULL, NULL, 15, 'checkbox', '{"options":["Sequence","Selection","Looping"],"question":"-","correct_options":["Sequence","Selection","Looping"]}', 1, 3, '<p>“Input nilai. Jika nilai ≥ 75 tampilkan lulus. Ulangi sampai lulus.”</p><p><br></p><p>Struktur apa saja yang terlibat</p>', 'Konsep Struktur Kontrol', '2026-02-28T10:51:50.370465+07:00'),
(187, 7, '<p>Looping digunakan untuk mengulang langkah beberapa kali, selama kondisi tertentu masih terpenuhi.  </p>', 'Looping digunakan ketika algoritma harus ____ langkah-langkah tertentu sampai suatu kondisi terpenuhi.', 'Looping digunakan ketika algoritma harus mengulang langkah-langkah tertentu sampai suatu kondisi terpenuhi.', 15, 'fill_in_the_blank', '{"blanks":["____"],"options":["menghentikan","mengulang","melewati"],"correct_answers":["mengulang"]}', 1, 4, '', 'Konsep Struktur Kontrol', '2026-02-28T10:51:50.370465+07:00'),
