(194, 9, '<p>Python bisa mencetak angka dari input.</p>', NULL, NULL, 10, 'multiple_choice', '{"correct":"Umur kamu 16","options":["Umur kamu 16","Umur kamu16","16","Umur kamu, 16"],"question":"Jika input adalah 16, apa yang tampil?"}', 3, 7, '<p>umur = input("Umur: ")</p><p>print("Umur kamu", umur)</p>', 'Input–Output', '2026-02-28T10:51:50.370465+07:00'),
