(341, 8, '<p>Insertion Sort selalu bekerja dari kiri ke kanan secara bertahap.</p>', 'Lengkapi simulasi [8 | 3, 5, 1]: Step 1: ____, Step 2: ____, Step 3: ____', 'Lengkapi simulasi [8 | 3, 5, 1]: Step 1: [3, 8 | 5, 1], Step 2: [3, 5, 8 | 1], Step 3: [1, 3, 5, 8 | ]', 10, 'fill_in_the_blank', '{"blanks":["____","____","____"],"options":["[3, 8 | 5, 1]","[3, 5, 8 | 1]","[1, 3, 5, 8 | ]"],"correct_answers":["[3, 8 | 5, 1]","[3, 5, 8 | 1]","[1, 3, 5, 8 | ]"]}', 9, 8, '<p>Lengkapi simulasi [8 | 3, 5, 1]: Step 1: ___, Step 2: ___, Step 3: ___</p>', 'Insertion Sort', '2026-02-28T10:51:50.370465+07:00'),
(342, 8, '<p>Insertion Sort menyusun data seperti menyusun kartu di tangan.</p>', 'Insertion Sort bekerja dengan cara ____ data.', 'Insertion Sort bekerja dengan cara menyisipkan data.', 10, 'fill_in_the_blank', '{"blanks":["____"],"options":["Memilih","menukar","menyisipkan","menghapus"],"correct_answers":["menyisipkan"]}', 9, 9, '<p>Insertion Sort bekerja dengan cara __________ data.</p>', 'Insertion Sort', '2026-02-28T10:51:50.370465+07:00'),
(343, 8, 'Setiap iterasi, bagian kiri semakin rapi.', NULL, NULL, 10, 'sorting', '{"code_lines":["[7, 4, 6, 2]","[4, 7, 6, 2]","[4, 6, 7, 2]","[2, 4, 6, 7]"],"correct_order":["[7, 4, 6, 2]","[4, 7, 6, 2]","[4, 6, 7, 2]","[2, 4, 6, 7]"]}', 9, 10, 'Urutkan langkah penyisipan insertion sort pada [7, 4, 6, 2]:', 'Insertion Sort', '2026-02-28T10:51:50.370465+07:00'),
(357, 7, 'IF digunakan untuk mengecek kondisi sebelum menjalankan aksi tertentu.', '____ kondisi THEN\n    aksi\n____', 'IF kondisi THEN\n    aksi\nENDIF', 10, 'fill_in_the_blank', '{"blanks":["____","____"],"options":["IF","ENDIF","ELSE"],"correct_answers":["IF","ENDIF"]}', 3, 4, 'Lengkapi struktur IF berikut:', 'Logika Selection', '2026-02-28T10:51:50.370465+07:00'),
(358, 7, 'ELSE dijalankan ketika kondisi IF bernilai salah. ELSE digunakan tanpa syarat tambahan.', 'IF ____ THEN\n    aksi_benar\n____\n    aksi_salah\nENDIF', 'IF kondisi THEN\n    aksi_benar\nELSE\n    aksi_salah\nENDIF', 10, 'fill_in_the_blank', '{"blanks":["____","____"],"options":["kondisi","ELSE"],"correct_answers":["kondisi","ELSE"]}', 3, 5, 'Lengkapi struktur IF-ELSE berikut:', 'Logika Selection', '2026-02-28T10:51:50.370465+07:00'),
(359, 7, '<p>Urutan penulisan IF–ELSE harus logis agar program dapat dibaca dengan benar.</p>', NULL, NULL, 10, 'sorting', '{"question":"","code_lines":["IF kondisi THEN","ENDIF","aksi"],"correct_order":["IF kondisi THEN","aksi","ENDIF"]}', 3, 6, '<p>Urutkan potongan berikut agar menjadi struktur IF-ELSE yang benar:</p>', 'Logika Selection', '2026-02-28T10:51:50.370465+07:00'),
(360, 7, 'ELSE IF digunakan saat ada lebih dari satu kondisi yang perlu dicek.', 'IF nilai >= 80 THEN\n    PRINT "Baik"\n____ nilai >= 60 THEN\n    PRINT "Cukup"\n____\n    PRINT "Kurang"\nENDIF', 'IF nilai >= 80 THEN\n    PRINT "Baik"\nELSE IF nilai >= 60 THEN\n    PRINT "Cukup"\nELSE\n    PRINT "Kurang"\nENDIF', 10, 'fill_in_the_blank', '{"blanks":["____","____"],"options":["ELSE IF","ELSE"],"correct_answers":["ELSE IF","ELSE"]}', 3, 7, 'Lengkapi bagian yang kosong pada logika ELSE IF:', 'Logika Selection', '2026-02-28T10:51:50.370465+07:00'),
(361, 7, 'Aksi harus berada di dalam blok IF atau ELSE.', 'IF suhu > 30 THEN\n    ____\nELSE\n    PRINT "Normal"\nENDIF', 'IF suhu > 30 THEN\n    PRINT "Panas"\nELSE\n    PRINT "Normal"\nENDIF', 10, 'fill_in_the_blank', '{"blanks":["____"],"options":["PRINT \"Panas\"","PRINT \"DINGIN\""],"correct_answers":["PRINT \"Panas\""]}', 3, 9, 'Lengkapi aksi yang tepat jika kondisi suhu di atas 30 benar:', 'Logika Selection', '2026-02-28T10:51:50.370465+07:00'),
(362, 7, 'Selection yang baik menghindari kondisi yang tumpang tindih.', NULL, NULL, 10, 'checkbox', '{"options":["Kondisi saling bertabrakan","ELSE sebagai kondisi terakhir","Urutan kondisi dari spesifik ke umum","ELSE IF tanpa IF"],"question":"Manakah yang menunjukkan penggunaan selection yang benar?","correct_options":["ELSE sebagai kondisi terakhir","Urutan kondisi dari spesifik ke umum"]}', 3, 10, 'Manakah yang menunjukkan penggunaan selection yang benar?', 'Logika Selection', '2026-02-28T10:51:50.370465+07:00'),
(363, 7, '<p>Kondisi pada ELSE IF hanya dicek jika kondisi sebelumnya salah.</p>', NULL, NULL, 10, 'multiple_choice', '{"correct":"Kurang","options":["Baik","Cukup","Kurang","Tidak ada output"],"question":"Jika nilai = 58, output yang muncul adalah…"}', 3, 8, '<pre class="ql-syntax" spellcheck="false">IF nilai &gt;= 80 THEN
&nbsp;&nbsp;PRINT "Baik"
ELSE IF nilai &gt;= 60 THEN
&nbsp;&nbsp;PRINT "Cukup"
ELSE
&nbsp;&nbsp;PRINT "Kurang"
ENDIF
</pre><p><br></p><p>Jika nilai = 58, output yang muncul adalah…</p>', 'Logika Selection', '2026-02-28T10:51:50.370465+07:00'),
(364, 7, '<p>Looping digunakan ketika suatu langkah perlu dijalankan berulang kali selama kondisi tertentu masih terpenuhi</p>', NULL, NULL, 10, 'multiple_choice', '{"correct":"Mengulang langkah berdasarkan kondisi","options":["Menjalankan langkah satu kali","Memilih satu dari dua jalur","Mengulang langkah berdasarkan kondisi","Menghentikan program"],"question":"Looping paling tepat digunakan ketika algoritma perlu…"}', 4, 1, '<p>Looping paling tepat digunakan ketika algoritma perlu…</p>', 'Logika Looping', '2026-02-28T10:51:50.370465+07:00'),
(365, 7, 'Berbeda dari sequence, looping memungkinkan satu langkah dijalankan lebih dari satu kali.', NULL, NULL, 10, 'multiple_choice', '{"correct":"False","options":["True","False"],"question":"Sequence dan looping sama-sama menjalankan langkah berulang."}', 4, 2, 'Sequence dan looping sama-sama menjalankan langkah berulang.', 'Logika Looping', '2026-02-28T10:51:50.370465+07:00'),
(366, 7, 'Looping digunakan ketika jumlah pengulangan tidak efisien jika ditulis satu per satu.', NULL, NULL, 10, 'multiple_choice', '{"correct":"Menampilkan angka 1 sampai 100","options":["Menghitung luas satu persegi","Menampilkan pesan satu kali","Menampilkan angka 1 sampai 100","Menentukan lulus atau tidak"],"question":"Masalah yang paling tepat menggunakan looping adalah…"}', 4, 3, 'Masalah yang paling tepat menggunakan looping adalah…', 'Logika Looping', '2026-02-28T10:51:50.370465+07:00'),
(367, 7, 'Agar looping dapat berhenti, diperlukan kondisi dan perubahan nilai.', 'Looping membutuhkan ____ untuk menentukan kapan berhenti dan ____ agar tidak berjalan tanpa akhir.', 'Looping membutuhkan kondisi untuk menentukan kapan berhenti dan perubahan nilai agar tidak berjalan tanpa akhir.', 10, 'fill_in_the_blank', '{"blanks":["____","____"],"options":["kondisi","output","perubahan nilai","input"],"correct_answers":["kondisi","perubahan nilai"]}', 4, 4, 'Lengkapi pernyataan tentang kebutuhan looping:', 'Logika Looping', '2026-02-28T10:51:50.370465+07:00'),
(368, 7, 'Setiap loop berjalan dengan alur yang konsisten dari awal hingga akhir.', NULL, NULL, 10, 'sorting', '{"code_lines":["Jalankan perintah","Periksa kondisi","Ubah nilai"],"correct_order":["Periksa kondisi","Jalankan perintah","Ubah nilai"]}', 4, 5, 'Urutkan alur umum looping:', 'Logika Looping', '2026-02-28T10:51:50.370465+07:00'),
(369, 7, 'Jika kondisi selalu bernilai benar dan tidak ada perubahan nilai, loop bisa berjalan tanpa hanti.', NULL, NULL, 10, 'multiple_choice', '{"correct":"True","options":["True","False"],"question":"Loop tanpa perubahan nilai berpotensi menyebabkan infinite loop."}', 4, 6, 'Loop tanpa perubahan nilai berpotensi menyebabkan infinite loop.', 'Logika Looping', '2026-02-28T10:51:50.370465+07:00'),
(370, 7, 'Selection memilih jalur, sedangkan looping mengulang jalur yang sama.', NULL, NULL, 10, 'checkbox', '{"options":["Digunakan untuk memilih satu dari dua jalur","Digunakan untuk menjalankan langkah berulang","Bergantung pada kondisi","Selalu dijalankan satu kali"],"question":"Manakah pernyataan yang benar tentang looping?","correct_options":["Digunakan untuk menjalankan langkah berulang","Bergantung pada kondisi"]}', 4, 7, 'Manakah pernyataan yang benar tentang looping?', 'Logika Looping', '2026-02-28T10:51:50.370465+07:00'),
(371, 7, 'Looping hanya efektif jika digunakan pada masalah yang tepat.', NULL, NULL, 10, 'multiple_choice', '{"correct":"Sequence","options":["Looping","Selection","Sequence","Loop bersarang"],"question":"Jika suatu langkah hanya perlu dijalankan sekali, maka struktur yang lebih tepat digunakan adalah…"}', 4, 8, 'Jika suatu langkah hanya perlu dijalankan sekali, maka struktur yang lebih tepat digunakan adalah…', 'Logika Looping', '2026-02-28T10:51:50.370465+07:00'),
(372, 7, '<p>Increment digunakan untuk menambah nilai variabel secara bertahap, biasanya sebesar 1.</p>', NULL, NULL, 10, 'multiple_choice', '{"correct":"True","options":["True","False"],"question":"x++ akan menambah nilai x sebesar 1."}', 5, 1, '<p>x++ akan menambah nilai x sebesar 1.</p>', 'Increment & Decrement', '2026-02-28T10:51:50.370465+07:00'),
(373, 7, 'Decrement kebalikan dari increment, yaitu mengurangi nilai variabel.', NULL, NULL, 10, 'multiple_choice', '{"correct":"x--","options":["x = x + 1","x++","x--","x += 2"],"question":"Manakah yang merupakan contoh decrement?"}', 5, 2, 'Manakah yang merupakan contoh decrement?', 'Increment & Decrement', '2026-02-28T10:51:50.370465+07:00'),
(374, 7, 'Increment dan decrement tidak mengubah tipe data, hanya nilainya.', NULL, NULL, 10, 'checkbox', '{"options":["Menambah atau mengurangi nilai variabel","Tidak mengubah tipe data","Digunakan untuk pengambilan keputusan","Selalu digunakan dalam loop"],"question":"Pernyataan yang BENAR tentang increment & decrement adalah…","correct_options":["Menambah atau mengurangi nilai variabel","Tidak mengubah tipe data"]}', 5, 3, 'Pernyataan yang BENAR tentang increment & decrement adalah…', 'Increment & Decrement', '2026-02-28T10:51:50.370465+07:00'),
(375, 7, 'Simbol ++ dan -- digunakan untuk menyingkat operasi increment dan decrement. Increment dan decrement bisa ditulis sebelum atau sesudah variabel.', NULL, NULL, 10, 'checkbox', '{"options":["++x","x++","--x"],"question":"Manakah penulisan yang VALID?","correct_options":["++x","x++","--x"]}', 5, 4, 'Manakah penulisan yang VALID?', 'Increment & Decrement', '2026-02-28T10:51:50.370465+07:00'),
(376, 7, 'Simbol operasi memiliki makna langsung terhadap perubahan nilai variabel.', NULL, NULL, 10, 'drag_and_drop', '{"items":["x++","x--"],"buckets":["nilai x bertambah 1","nilai x berkurang 1"],"correct_assignment":{"nilai x berkurang 1":["x--"],"nilai x bertambah 1":["x++"]}}', 5, 5, 'Pasangkan simbol dengan efeknya.', 'Increment & Decrement', '2026-02-28T10:51:50.370465+07:00'),
(377, 7, '<p>Selain menggunakan operator ++ untuk menambah nilai sebesar 1, increment juga dapat dilakukan dengan operator penugasan gabungan.</p><p>Operator += digunakan untuk menambahkan nilai tertentu ke nilai variabel yang sudah ada.</p>', 'x = 5
x += 3

Kode tersebut memiliki arti bahwa nilai x menjadi ____.', 'x = 5
x += 3

Kode tersebut memiliki arti bahwa nilai x menjadi 8.', 10, 'fill_in_the_blank', '{"blanks":["____"],"options":["6","5","8","15"],"correct_answers":["8"]}', 5, 6, '<p><br></p>', 'Increment & Decrement', '2026-02-28T10:51:50.370465+07:00'),
(378, 7, 'Increment langsung mengubah nilai variabel setelah dijalankan.', NULL, NULL, 10, 'multiple_choice', '{"correct":"6","options":["4","5","6","Tidak berubah"],"question":"Jika x = 5, setelah menjalankan x++, nilai x adalah…"}', 5, 7, 'Jika x = 5, setelah menjalankan x++, nilai x adalah…', 'Increment & Decrement', '2026-02-28T10:51:50.370465+07:00'),
(379, 7, 'Urutan eksekusi memengaruhi hasil akhir nilai variabel.', 'Jika x = 3, setelah x-- nilai x menjadi ____, lalu setelah x++ nilai x menjadi ____.', 'Jika x = 3, setelah x-- nilai x menjadi 2, lalu setelah x++ nilai x menjadi 3.', 10, 'fill_in_the_blank', '{"blanks":["____","____"],"options":["2","3","4"],"correct_answers":["2","3"]}', 5, 8, 'Lengkapi nilai variabel x berikut:', 'Increment & Decrement', '2026-02-28T10:51:50.370465+07:00'),
(380, 7, '<p>Increment dan decrement bisa digunakan tanpa loop untuk mengontrol nilai.</p>', 'Jika x = 10, setelah x--; x--;, nilai akhir x adalah ____.', 'Jika x = 10, setelah x--; x--;, nilai akhir x adalah 8.', 10, 'fill_in_the_blank', '{"blanks":["____"],"options":["7","8","9","10"],"correct_answers":["8"]}', 5, 9, '<p><br></p>', 'Increment & Decrement', '2026-02-28T10:51:50.370465+07:00'),
(381, 7, 'Increment digunakan untuk mengubah nilai variabel sebelum digunakan pada baris berikutnya.', 'x = 0\n____\nPRINT x', 'x = 0\nx++\nPRINT x', 10, 'fill_in_the_blank', '{"blanks":["____"],"options":["x++","x--","x += 0","x = x"],"correct_answers":["x++"]}', 5, 10, 'Lengkapi kode berikut agar output yang ditampilkan adalah 1.', 'Increment & Decrement', '2026-02-28T10:51:50.370465+07:00'),
(382, 7, '<p>Decrement mengurangi nilai variabel setiap kali dijalankan.</p>', 'x = 2\n____\nPRINT x', 'x = 2\nx--\nPRINT x', 10, 'fill_in_the_blank', '{"blanks":["____"],"options":["x--","x++","x+=1"],"correct_answers":["x--"]}', 5, 11, '<p>Susun dua baris kode berikut agar nilai akhir x menjadi 1.</p>', 'Increment & Decrement', '2026-02-28T10:51:50.370465+07:00'),
(383, 7, '<p>Nilai awal dan increment menentukan angka pertama yang ditampilkan oleh loop.</p>', NULL, NULL, 10, 'multiple_choice', '{"correct":"2","options":["1","2","3","5"],"question":"Jawablah pertanyaan di atas"}', 5, 12, '<pre class="ql-syntax" spellcheck="false">i = 2
WHILE i &lt;= 5
&nbsp;&nbsp;tampilkan i
&nbsp;&nbsp;i = i + 1
ENDWHILE
</pre><p><br></p><p>Angka pertama yang ditampilkan adalah…</p>', 'Increment & Decrement', '2026-02-28T10:51:50.370465+07:00'),
(384, 7, '<p>While loop menjalankan pengulangan selama kondisinya bernilai benar. Jika kondisi salah, loop langsung berhenti.</p>', NULL, NULL, 10, 'multiple_choice', '{"correct":"True","options":["True","False"],"question":"While loop akan terus berjalan selama kondisi terpenuhi."}', 6, 1, '<p>While loop akan terus berjalan selama kondisi terpenuhi.</p>', 'While Loop', '2026-02-28T10:51:50.370465+07:00'),
(385, 7, 'While cocok saat jumlah pengulangan belum diketahui sejak awal, dan bergantung pada kondisi tertentu.', NULL, NULL, 10, 'multiple_choice', '{"correct":"Mengulang sampai user memasukkan password benar","options":["Menampilkan angka 1 sampai 10","Mengulang sampai user memasukkan password benar","Mengulang 5 kali saja","Menampilkan bilangan genap dari 2 sampai 20"],"question":"Manakah masalah yang paling cocok memakai while loop?"}', 6, 2, 'Manakah masalah yang paling cocok memakai while loop?', 'While Loop', '2026-02-28T10:51:50.370465+07:00'),
(386, 7, 'While selalu mengecek kondisi sebelum menjalankan perintah.', NULL, NULL, 10, 'sorting', '{"code_lines":["Jalankan perintah","Cek kondisi","Ubah nilai"],"correct_order":["Cek kondisi","Jalankan perintah","Ubah nilai"]}', 6, 3, 'Urutkan langkah while loop:', 'While Loop', '2026-02-28T10:51:50.370465+07:00'),
(387, 7, 'Agar loop berhenti, nilai harus berubah. Jika nilainya tidak berubah, loop bisa berjalan tanpa akhir.', NULL, NULL, 10, 'multiple_choice', '{"correct":"True","options":["True","False"],"question":"Jika nilai tidak berubah, while loop dapat menjadi infinite loop."}', 6, 4, 'Jika nilai tidak berubah, while loop dapat menjadi infinite loop.', 'While Loop', '2026-02-28T10:51:50.370465+07:00'),
(388, 7, 'While loop akan terus berjalan selama kondisi bernilai benar, dan berhenti ketika kondisi menjadi salah.', NULL, NULL, 10, 'multiple_choice', '{"correct":"i < 7","options":["i < 7","i > 7","i = 7","i ≥ 7"],"question":"Ingin menampilkan angka selama nilai i masih di bawah 7. Kondisi while yang paling tepat adalah…"}', 6, 5, 'Ingin menampilkan angka selama nilai i masih di bawah 7. Kondisi while yang paling tepat adalah…', 'While Loop', '2026-02-28T10:51:50.370465+07:00'),
(389, 7, '<p>Output bergantung pada nilai awal, kondisi, dan perubahan nilai.</p>', NULL, NULL, 10, 'multiple_choice', '{"correct":"2, 3, 4","options":["2, 3","2, 3, 4","3, 4, 5","2, 3, 4, 5"],"question":"Outputnya adalah…"}', 6, 6, '<p>i = 2</p><p>WHILE i &lt; 5</p><p>&nbsp;&nbsp;tampilkan i</p><p>&nbsp;&nbsp;i = i + 1</p><p>ENDWHILE</p><p><br></p><p><br></p><p>Berapakah output dari kode while loop tersebut?</p>', 'While Loop', '2026-02-28T10:51:50.370465+07:00'),
(390, 7, 'Loop maju membutuhkan increment agar nilai bertambah.', 'i = 1\nWHILE i ≤ 4\n    tampilkan i\n    i = i ____ 1\nENDWHILE', 'i = 1\nWHILE i ≤ 4\n    tampilkan i\n    i = i + 1\nENDWHILE', 10, 'fill_in_the_blank', '{"blanks":["____"],"options":["+","-"],"correct_answers":["+"]}', 6, 7, 'Buat agar nilai bertambah (loop maju):', 'While Loop', '2026-02-28T10:51:50.370465+07:00'),
(391, 7, 'Loop juga bisa mundur, selama nilainya dikurangi, yaitu dengan menggunakan decrement.', 'i = 5\nWHILE i ≥ 3\n    tampilkan i\n    i = i ____ 1\nENDWHILE', 'i = 5\nWHILE i ≥ 3\n    tampilkan i\n    i = i - 1\nENDWHILE', 10, 'fill_in_the_blank', '{"blanks":["____"],"options":["+","-"],"correct_answers":["-"]}', 6, 8, 'Lengkapi agar menghasilkan urutan mundur (5, 4, 3):', 'While Loop', '2026-02-28T10:51:50.370465+07:00'),
(392, 7, '<p>Loop berhenti saat kondisi bernilai salah.</p>', NULL, NULL, 10, 'multiple_choice', '{"correct":"3","options":["1","2","3","0"],"question":"Jawab pertanyaan di atas"}', 6, 9, '<p>i = 1</p><p>WHILE i &lt; 3</p><p>&nbsp;&nbsp;tampilkan i</p><p>&nbsp;&nbsp;i = i + 1</p><p>ENDWHILE</p><p><br></p><p><br></p><p>Loop berhenti ketika i bernilai…</p>', 'While Loop', '2026-02-28T10:51:50.370465+07:00'),
(393, 7, 'While loop selalu diawali dengan kondisi.', '____ i < 3\n    tampilkan i\n    i = i + 1\n____', 'WHILE i < 3\n    tampilkan i\n    i = i + 1\nENDWHILE', 10, 'fill_in_the_blank', '{"blanks":["____","____"],"options":["WHILE","ENDWHILE","FOR","ENDFOR"],"correct_answers":["WHILE","ENDWHILE"]}', 6, 10, 'Lengkapi struktur While loop berikut:', 'While Loop', '2026-02-28T10:51:50.370465+07:00'),
(394, 7, '<p>For loop digunakan jika jumlah pengulangannya sudah diketahui.</p>', NULL, NULL, 10, 'multiple_choice', '{"correct":"True","options":["True","False"],"question":"For loop cocok untuk pengulangan yang jumlahnya jelas."}', 7, 1, '<p>For loop cocok untuk pengulangan yang jumlahnya jelas.</p>', 'For Loop', '2026-02-28T10:51:50.370465+07:00'),
(395, 7, 'For loop memiliki: Nilai awal, Nilai akhir, Arah langkah (maju atau mundur).', NULL, NULL, 10, 'multiple_choice', '{"correct":"Input pengguna","options":["Nilai awal","Nilai akhir","Arah langkah","Input pengguna"],"question":"Bagian mana bukan elemen for loop?"}', 7, 2, 'Bagian mana bukan elemen for loop?', 'For Loop', '2026-02-28T10:51:50.370465+07:00'),
(396, 7, 'For loop maju bergerak dari angka kecil → besar. Contoh pola: 1, 2, 3, 4,...', 'FOR i dari 1 ____ 4\n    tampilkan i\nENDFOR', 'FOR i dari 1 ke 4\n    tampilkan i\nENDFOR', 10, 'fill_in_the_blank', '{"blanks":["____"],"options":["ke","sampai","dari"],"correct_answers":["ke"]}', 7, 3, 'Lengkapi sintaks for loop maju berikut:', 'For Loop', '2026-02-28T10:51:50.370465+07:00'),
(397, 7, '<p>Output bergantung pada nilai awal dan akhir.</p>', NULL, NULL, 10, 'multiple_choice', '{"correct":"2, 3, 4, 5","options":["2, 3","2, 3, 4, 5","1, 2, 3, 4","5, 4, 3"],"question":"Apa output dari kode tersebut?"}', 7, 4, '<p>FOR i dari 2 ke 5</p><p>&nbsp;&nbsp;tampilkan i</p><p>ENDFOR</p><p><br></p><p>Apa output dari kode tersebut?</p>', 'For Loop', '2026-02-28T10:51:50.370465+07:00'),
(398, 7, 'For loop juga bisa mundur dari angka besar → kecil.', NULL, NULL, 10, 'multiple_choice', '{"correct":"6, 5, 4, 3","options":["6, 5, 4, 3","3, 4, 5, 6","6, 4, 2","5, 4, 3"],"question":"FOR i dari 6 ke 3 menghasilkan urutan…"}', 7, 5, 'FOR i dari 6 ke 3 menghasilkan urutan…', 'For Loop', '2026-02-28T10:51:50.370465+07:00'),
